values ('af2e359b-3442-4625-a710-22106ab8f24d', 'align-chiro', 'Align Chiropractic', 'Chiropractic clinic for back, neck & joints', 'Authorised chiropractors helping with back pain, neck pain, headaches and sports injuries. No referral needed.', 'chiropractic', '🦴', '#6fb7ff', 'https://images.unsplash.com/photo-1552693673-1bf958298935?auto=format&fit=crop&w=1600&q=70', 'Gammel Kongevej 110', '1850 Frederiksberg C', '+45 XX XX XX XX', 'reception@align.demo', '2 hours free parking with a parking disc on Gammel Kongevej. Elevator access.', 'You get a public subsidy (''sygesikring'' group 1) for chiropractic treatment – it''s deducted automatically. ''Sygeforsikringen danmark'' also covers part of the price. No referral from your doctor is needed.', 'https://www.google.com/search?q=Align+Chiropractic+reviews')
on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
insert into clinic.clinic_settings (clinic_id, opening_hours, booking, payment_methods, faq)
values ('af2e359b-3442-4625-a710-22106ab8f24d', '[{"day":0,"open":"00:00","close":"00:00","closed":true},{"day":1,"open":"07:30","close":"18:00"},{"day":2,"open":"07:30","close":"18:00"},{"day":3,"open":"07:30","close":"18:00"},{"day":4,"open":"07:30","close":"18:00"},{"day":5,"open":"07:30","close":"15:00"},{"day":6,"open":"00:00","close":"00:00","closed":true}]'::jsonb, '{"enabled":true,"slotMinutes":10,"bufferMinutes":0,"minNoticeHours":1,"maxDaysAhead":60,"cancellationHours":24,"lateCancellationFee":0,"confirmNewClients":false,"rules":"New patients start with a first consultation (45 min) incl. examination. Rebook or cancel up to 24 hours before. Acute pain? Call us – we keep same-day slots free."}'::jsonb, array['card','mobilepay','insurance']::text[], '[{"question":"Do I need a referral?","answer":"No, you don''t need a referral to see a chiropractor. Just book a first consultation.","keywords":["referral","doctor","henvisning","gp"]},{"question":"What happens at the first consultation?","answer":"We go through your history, do a thorough examination and – if appropriate – start treatment the same day. Plan 45 minutes and wear comfortable clothes.","keywords":["first time","first consultation","first visit","what happens","new patient"]},{"question":"I''m in acute pain – can I come today?","answer":"Yes, we keep acute slots free every day. Ask me for today''s first available time, or call the clinic directly.","keywords":["acute","emergency","today","urgent","pain","hurt","locked"]},{"question":"How do I pay?","answer":"You pay after your appointment by card or MobilePay. We don''t take cash.","keywords":["pay","payment","mobilepay","card","cash"]},{"question":"Do you send a reminder?","answer":"Yes – you get a text message the day before your appointment with the time and a link to rebook or cancel.","keywords":["reminder","sms","text message","confirmation"]}]'::jsonb)
