values ('c0fc127a-134c-4ff5-a5fa-07f2fd25b118', 'movewell-physio', 'MoveWell Physio', 'Physiotherapy & sports rehab', 'Physiotherapists specialised in sports injuries, back pain and rehab after surgery. With or without a doctor''s referral.', 'physio', '🏃', '#9adf6a', 'https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&fit=crop&w=1600&q=70', 'Amagerbrogade 150', '2300 Copenhagen S', '+45 XX XX XX XX', 'hello@movewell.demo', 'Free parking in the courtyard behind the clinic. Metro: Amagerbro, 3 min walk.', 'With a referral from your GP you get a public subsidy (approx. 40%) that is deducted automatically. We also work with most health insurances (e.g. Skandia, Tryg, PFA) – we invoice them directly.', 'https://www.google.com/search?q=MoveWell+Physio+reviews')
on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
insert into clinic.clinic_settings (clinic_id, opening_hours, booking, payment_methods, faq)
values ('c0fc127a-134c-4ff5-a5fa-07f2fd25b118', '[{"day":0,"open":"00:00","close":"00:00","closed":true},{"day":1,"open":"07:00","close":"19:00"},{"day":2,"open":"07:00","close":"19:00"},{"day":3,"open":"07:00","close":"19:00"},{"day":4,"open":"07:00","close":"19:00"},{"day":5,"open":"07:00","close":"16:00"},{"day":6,"open":"00:00","close":"00:00","closed":true}]'::jsonb, '{"enabled":true,"slotMinutes":15,"bufferMinutes":10,"minNoticeHours":3,"maxDaysAhead":60,"cancellationHours":24,"lateCancellationFee":200,"confirmNewClients":false,"rules":"New patients start with an initial assessment (60 min). Bring your referral if you have one. Cancel or rebook up to 24 hours before – later cancellations are charged DKK 200."}'::jsonb, array['card','mobilepay','insurance','invoice']::text[], '[{"question":"Do I need a referral?","answer":"No – you can book without a referral. With a referral from your GP you get a public subsidy of about 40%.","keywords":["referral","doctor","gp","henvisning"]},{"question":"What should I wear?","answer":"Comfortable clothes you can move in – shorts are great for knee and hip problems. We have changing rooms.","keywords":["wear","clothes","bring","dress"]},{"question":"How do I pay?","answer":"You pay after your appointment by card or MobilePay. We don''t take cash.","keywords":["pay","payment","mobilepay","card","cash"]},{"question":"Do you send a reminder?","answer":"Yes – you get a text message the day before your appointment with the time and a link to rebook or cancel.","keywords":["reminder","sms","text message","confirmation"]}]'::jsonb)
on conflict (clinic_id) do nothing;
