values ('f6a70907-a422-4933-abeb-2f05309257eb', 'smile-dental', 'Smile Dental Clinic', 'Friendly dentist for the whole family', 'Modern dental clinic with check-ups, hygienist, fillings, whitening and emergency appointments. Anxious patients are very welcome.', 'dental', '🦷', '#7ad3f2', 'https://images.unsplash.com/photo-1629909613654-28e377c37b09?auto=format&fit=crop&w=1600&q=70', 'Lyngbyvej 32', '2100 Copenhagen Ø', '+45 XX XX XX XX', 'tand@smiledental.demo', 'Free parking for patients behind the building (entrance from Lyngbyvej).', 'The public subsidy for dental care is deducted automatically. With ''Sygeforsikringen danmark'' you get additional reimbursement – we send it directly, so you only pay your share.', 'https://www.google.com/search?q=Smile+Dental+Clinic+reviews')
on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
insert into clinic.clinic_settings (clinic_id, opening_hours, booking, payment_methods, faq)
values ('f6a70907-a422-4933-abeb-2f05309257eb', '[{"day":0,"open":"00:00","close":"00:00","closed":true},{"day":1,"open":"08:00","close":"17:00"},{"day":2,"open":"08:00","close":"17:00"},{"day":3,"open":"08:00","close":"17:00"},{"day":4,"open":"08:00","close":"17:00"},{"day":5,"open":"08:00","close":"14:00"},{"day":6,"open":"00:00","close":"00:00","closed":true}]'::jsonb, '{"enabled":true,"slotMinutes":15,"bufferMinutes":10,"minNoticeHours":2,"maxDaysAhead":120,"cancellationHours":24,"lateCancellationFee":350,"confirmNewClients":true,"rules":"New patients are confirmed by the clinic within one working day. Cancel or rebook up to 24 hours before – later cancellations are charged DKK 350. Emergency? Call us before 10:00 for a same-day appointment."}'::jsonb, array['card','mobilepay','insurance']::text[], '[{"question":"I''m nervous about the dentist – can you help?","answer":"Absolutely. Tell us when you book and we''ll plan extra time, explain everything along the way and agree on a stop signal. We can also offer calming medication.","keywords":["nervous","anxious","anxiety","scared","afraid","fear"]},{"question":"I have a toothache – can I come today?","answer":"Yes, we have emergency appointments every weekday. Ask me for today''s first available emergency time, or call before 10:00.","keywords":["toothache","tooth ache","pain","emergency","broken","cracked","today","acute"]},{"question":"How often should I have a check-up?","answer":"Most adults should come every 12–18 months – we''ll tell you your recommended interval after your check-up.","keywords":["how often","interval","every"]},{"question":"How do I pay?","answer":"You pay after your appointment by card or MobilePay. We don''t take cash.","keywords":["pay","payment","mobilepay","card","cash"]},{"question":"Do you send a reminder?","answer":"Yes – you get a text message the day before your appointment with the time and a link to rebook or cancel.","keywords":["reminder","sms","text message","confirmation"]}]'::jsonb)
on conflict (clinic_id) do nothing;
