values ('afad2406-3f73-4b00-a852-2b78b7e6bd7e', '[{"day":0,"open":"00:00","close":"00:00","closed":true},{"day":1,"open":"10:00","close":"19:00"},{"day":2,"open":"10:00","close":"19:00"},{"day":3,"open":"10:00","close":"19:00"},{"day":4,"open":"10:00","close":"19:00"},{"day":5,"open":"10:00","close":"18:00"},{"day":6,"open":"10:00","close":"16:00"}]'::jsonb, '{"enabled":true,"slotMinutes":15,"bufferMinutes":10,"minNoticeHours":2,"maxDaysAhead":60,"cancellationHours":24,"lateCancellationFee":400,"confirmNewClients":false,"rules":"Cancel or rebook for free up to 24 hours before. Later cancellations and no-shows are charged DKK 400. Please arrive with a clean face for peels and microneedling."}'::jsonb, array['card','mobilepay']::text[], '[{"question":"Which treatment is right for my skin?","answer":"Book a free 30-minute skin consultation – our skin therapist analyses your skin and recommends a plan. No obligation.","keywords":["which treatment","right for","recommend","my skin","acne","pigment","wrinkles"]},{"question":"Is there downtime after microneedling?","answer":"Expect 1–2 days of redness. Avoid sun, make-up and exercise for 24 hours. We give you aftercare products to take home.","keywords":["downtime","after","aftercare","red","redness","recovery"]},{"question":"How do I pay?","answer":"You pay after your appointment by card or MobilePay. We don''t take cash.","keywords":["pay","payment","mobilepay","card","cash"]},{"question":"Do you send a reminder?","answer":"Yes – you get a text message the day before your appointment with the time and a link to rebook or cancel.","keywords":["reminder","sms","text message","confirmation"]}]'::jsonb)
