values ('851a7b0b-ec7e-4b45-a5a1-407c5d5672ce', 'step-foot', 'Step Foot Clinic', 'State-registered podiatrists', 'Foot care by state-registered podiatrists: treatments, ingrown toenails, diabetic foot care, warts and custom insoles.', 'podiatry', '🦶', '#f2c46b', 'https://images.unsplash.com/photo-1519415510236-718bdfcd89c8?auto=format&fit=crop&w=1600&q=70', 'Frederikssundsvej 88', '2400 Copenhagen NV', '+45 XX XX XX XX', 'fod@stepfoot.demo', 'Free 2-hour parking in front of the clinic. Step-free access.', 'With a doctor''s referral for diabetes (or certain other conditions) you get a public subsidy for podiatry. ''Sygeforsikringen danmark'' also reimburses part of foot treatments.', 'https://www.google.com/search?q=Step+Foot+Clinic+reviews')
on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, description = excluded.description;
