values ('851a7b0b-ec7e-4b45-a5a1-407c5d5672ce', '[{"day":0,"open":"00:00","close":"00:00","closed":true},{"day":1,"open":"08:00","close":"17:00"},{"day":2,"open":"08:00","close":"17:00"},{"day":3,"open":"08:00","close":"17:00"},{"day":4,"open":"08:00","close":"17:00"},{"day":5,"open":"08:00","close":"15:00"},{"day":6,"open":"00:00","close":"00:00","closed":true}]'::jsonb, '{"enabled":true,"slotMinutes":15,"bufferMinutes":10,"minNoticeHours":2,"maxDaysAhead":60,"cancellationHours":24,"lateCancellationFee":200,"confirmNewClients":false,"rules":"Cancel or rebook up to 24 hours before – later cancellations are charged DKK 200. Diabetic patients with a referral get a public subsidy."}'::jsonb, array['card','mobilepay','insurance']::text[], '[{"question":"How often should I get a foot treatment?","answer":"Most clients come every 6–8 weeks. With diabetes we usually recommend every 4–6 weeks.","keywords":["how often","interval","every"]},{"question":"Can you help with an ingrown toenail today?","answer":"Often yes – ask me for today''s first free time for ''Ingrown toenail''. If it''s red and swollen, please mention it when booking.","keywords":["ingrown","toenail","nail","infection","swollen"]},{"question":"How do I pay?","answer":"You pay after your appointment by card or MobilePay. We don''t take cash.","keywords":["pay","payment","mobilepay","card","cash"]},{"question":"Do you send a reminder?","answer":"Yes – you get a text message the day before your appointment with the time and a link to rebook or cancel.","keywords":["reminder","sms","text message","confirmation"]}]'::jsonb)
on conflict (clinic_id) do nothing;
